SELECT
  (SELECT COUNT(*) FROM m) AS 清单脚本数,
  (SELECT COUNT(*) FROM m x JOIN yj_schema_log l ON l.script_name = x.name) AS 已登记,
  (SELECT COUNT(*) FROM m x JOIN yj_schema_log l ON l.script_name = x.name WHERE l.content_hash = x.hash) AS 已登记_哈希一致,
  (SELECT COUNT(*) FROM m x JOIN yj_schema_log l ON l.script_name = x.name WHERE l.content_hash <> x.hash) AS 已登记_内容已变,
  (SELECT COUNT(*) FROM m x WHERE NOT EXISTS (SELECT 1 FROM yj_schema_log l WHERE l.script_name = x.name)) AS 未登记_待执行,
  (SELECT COUNT(*) FROM yj_schema_log l WHERE NOT EXISTS (SELECT 1 FROM m x WHERE x.name = l.script_name)) AS 登记表中不在清单的行数;
GO
