SELECT 类别, script_name FROM (
  SELECT N'未登记(待执行/新增)' AS 类别, x.name AS script_name FROM m x
    WHERE NOT EXISTS (SELECT 1 FROM yj_schema_log l WHERE l.script_name = x.name)
  UNION ALL
  SELECT N'内容已变(DbSync 会重跑)', x.name FROM m x
    JOIN yj_schema_log l ON l.script_name = x.name WHERE l.content_hash <> x.hash
) z ORDER BY 类别, script_name;